#!/usr/bin/env bash
# GraphTrack chain: E1 probe -> E2 oracle (go/no-go) -> E3 retrain -> E4b val ->
# E4 test -> E5 unseen-recipe (train x2, test x2). Every stage skips if its
# output exists, waits for a free GPU, retries on co-tenant OOM, and honours
# outputs/review_v4/STOP_CHAIN. Launch detached:
#
#   setsid nohup bash scripts/cc4d_graphtrack_chain.sh > /dev/null 2>&1 < /dev/null &
#
# Do not edit this file while it runs (bash reads scripts incrementally).
set -uo pipefail
cd "$(dirname "$0")/.."
PY=/mnt/hdd/Rafin/miniconda3/bin/python
OUT=outputs/review_v4
ADAPTER=outputs/lora_graphtrack
ADAPTER_HOLD=outputs/lora_graphtrack_holdout
ADAPTER_HOLD_NOGR=outputs/lora_nograph_holdout
R11_ADAPTER=outputs/lora_cc4d_8class_fixedptr
HOLDOUT=data/splits/recipe_holdout_v1.json
HOLDOUT_SEC=data/step_seconds_holdout_v1.json
LOG=logs/cc4d_graphtrack_chain.log
NEED_INFER=${NEED_INFER_MIB:-28000}
NEED_TRAIN=${NEED_TRAIN_MIB:-66000}
CORRUPT=${CORRUPT_RATE:-0.35}
export HF_HUB_OFFLINE=1 HF_HUB_DISABLE_XET=1

mkdir -p "$OUT" logs
exec >> "$LOG" 2>&1
say() { echo "[$(date '+%F %T')] $*"; }
check_stop() { [ -f "$OUT/STOP_CHAIN" ] && { say "STOP_CHAIN — aborting"; exit 0; }; return 0; }

wait_for_gpu() {
    local ok=0 q used total util free min_free=${1:-$NEED_INFER}
    say "waiting for GPU (need >=${min_free} MiB free)"
    while [ $ok -lt 3 ]; do
        check_stop
        q=$(nvidia-smi --query-gpu=memory.used,memory.total,utilization.gpu --format=csv,noheader,nounits 2>/dev/null | head -1 | tr -d ',')
        read -r used total util <<< "$q"
        if ! [[ "${used:-}" =~ ^[0-9]+$ && "${total:-}" =~ ^[0-9]+$ ]]; then
            ok=0; say "gpu unavailable — waiting"; sleep 60; continue
        fi
        free=$(( total - used ))
        if [ "$free" -ge "$min_free" ]; then ok=$(( ok + 1 )); say "gpu ok ($ok/3): free=${free}MiB";
        else ok=0; say "gpu busy: free=${free}MiB"; fi
        sleep 20
    done
}

attempt() {
    local label="$1"; shift
    local tries=0 max=${STAGE_MAX_TRIES:-8}
    while [ "$tries" -lt "$max" ]; do
        tries=$(( tries + 1 ))
        if "$@"; then return 0; fi
        say "$label: attempt $tries/$max failed (co-tenant OOM?) — backing off"
        check_stop; sleep 180; wait_for_gpu "$NEED_INFER"
    done
    say "$label: giving up after $max attempts"; return 1
}

stage_infer() {   # label, output preds json, then args...
    local label="$1" preds="$2"; shift 2
    if [ -e "$preds" ]; then say "SKIP $label — $preds present"; return 0; fi
    check_stop; wait_for_gpu "$NEED_INFER"; say "$label: start"
    attempt "$label" $PY scripts/cc4d_collect_preds.py --resume --save_preds "$preds" "$@" \
        && say "$label: done" || { say "$label FAILED"; return 1; }
}

stage_train() {   # label, adapter dir, then args...
    local label="$1" adapter="$2"; shift 2
    if [ -e "$adapter/adapter_model.safetensors" ]; then say "SKIP $label — adapter present"; return 0; fi
    check_stop; wait_for_gpu "$NEED_TRAIN"; say "$label: start"
    attempt "$label" $PY scripts/cc4d_lora_train.py --output_dir "$adapter" --no_wandb --resume "$@" \
        && say "$label: done" || { say "$label FAILED"; return 1; }
}

say "=== GraphTrack chain started (pid $$) ==="

# E1: zero-shot step-recognition probe on 10 stratified val recordings (compact prompt timing)
stage_infer "E1" "$OUT/e1_zs_belief_val10_preds.json" --split val --limit 10 --stratify --stride 4 \
    --prompt_variant belief --tracker belief --max_new_tokens 48 --out "$OUT/e1_zs_belief_val10_eval.json" || exit 1

# E2: oracle step context with the existing R11 adapter and the legacy prompt (go/no-go)
stage_infer "E2" "$OUT/e2_oracle_r11_test_preds.json" --split test --stride 4 --prompt_variant graph \
    --tracker pointer --oracle_step --lora_adapter "$R11_ADAPTER" --out "$OUT/e2_oracle_r11_test_eval.json" || exit 1
if [ ! -e "$OUT/row_e2_oracle_r11_test.json" ]; then
    P=outputs/decision_v2/decision_params_lora.json
    $PY scripts/cc4d_decision_eval.py --preds "$OUT/e2_oracle_r11_test_preds.json" --split test \
        --tau "$($PY -c "import json;print(json.load(open('$P'))['tau'])")" \
        --smooth_k "$($PY -c "import json;print(json.load(open('$P'))['smooth_k'])")" \
        --min_consecutive "$($PY -c "import json;print(json.load(open('$P'))['min_consecutive'])")" \
        --gate_mode "$($PY -c "import json;print(json.load(open('$P'))['gate_mode'])")" \
        --out "$OUT/row_e2_oracle_r11_test.json" || true
    $PY scripts/cc4d_bootstrap_compare.py --preds "$OUT/e2_oracle_r11_test_preds.json" --params "$P" \
        --preds_b outputs/decision_v2/lora_fixedptr_test_preds.json --params_b "$P" --split test \
        --label e2_oracle_vs_r11 || true
    say "E2 go/no-go: see outputs/decision_v2/bootstrap_e2_oracle_vs_r11.json"
fi

# E3: GraphTrack adapter (belief prompt, corrupted context, step letter supervised)
stage_train "E3" "$ADAPTER" --prompt_variant belief --context_mode corrupt --corrupt_rate "$CORRUPT" || exit 1

# E4b: validation pass for fusion / decision selection
stage_infer "E4b" "$OUT/gt_val_preds.json" --split val --stride 4 --prompt_variant belief --tracker belief \
    --max_new_tokens 48 --lora_adapter "$ADAPTER" --out "$OUT/gt_val_eval.json" || exit 1

# E4: full test pass
stage_infer "E4" "$OUT/gt_test_preds.json" --split test --stride 4 --prompt_variant belief --tracker belief \
    --max_new_tokens 48 --lora_adapter "$ADAPTER" --out "$OUT/gt_test_eval.json" || exit 1

# E5: unseen recipes — GraphTrack vs graph-free, both trained on the other 20 recipes
stage_train "E5-train-gt" "$ADAPTER_HOLD" --prompt_variant belief --context_mode corrupt --corrupt_rate "$CORRUPT" \
    --recipe_holdout "$HOLDOUT" || exit 1
stage_train "E5-train-nograph" "$ADAPTER_HOLD_NOGR" --prompt_variant nograph --recipe_holdout "$HOLDOUT" || exit 1
stage_infer "E5-test-gt" "$OUT/gt_holdout_test_preds.json" --split test --stride 4 --prompt_variant belief --tracker belief \
    --max_new_tokens 48 --lora_adapter "$ADAPTER_HOLD" --recipe_holdout "$HOLDOUT" --step_seconds "$HOLDOUT_SEC" \
    --out "$OUT/gt_holdout_test_eval.json" || exit 1
stage_infer "E5-test-nograph" "$OUT/nograph_holdout_test_preds.json" --split test --stride 4 --prompt_variant nograph \
    --tracker pointer --lora_adapter "$ADAPTER_HOLD_NOGR" --recipe_holdout "$HOLDOUT" --step_seconds "$HOLDOUT_SEC" \
    --out "$OUT/nograph_holdout_test_eval.json" || exit 1

say "=== GraphTrack chain finished ==="
